function armorRaw(p,refs={MAXHP:100,MAXMP:50,ATT:50,DEF:25,DEX:50,SPD:50,VIT:50,WIS:50}){const raw={...p.flat};for(const r of p.relative)raw[r.target]=(raw[r.target]||0)+(refs[r.basis]||0)*r.ratio;return raw}
