function armorRecipe(p){const raw=armorRaw(p),secondary=Object.entries(raw).filter(([k,v])=>k!=='DEF'&&v>0).length,tax=1+.04*secondary+(p.procs.length?.08:0),def=Math.max(0,raw.DEF||0);if(p.kind==='plate'&&!def&&(raw.VIT||0)>=20)return {effect:'heal',amount:12,cd:3.5};if(p.kind==='plate')return {effect:'block',amount:Math.max(3,Math.round(3.2*Math.min(9.6,Math.max(1,3.125+(def-5)*(23/2.75-3.125)/23))/tax)),cd:3.2};if(p.kind==='leather')return {effect:'dodge',amount:1,cd:Math.round(Math.min(13,Math.max(5.5,(10-(def-5)*3.5/17)*tax))*100)/100};return {effect:'mana',amount:2,cd:Math.round(Math.min(6,2.93*tax/Math.max(.45,Math.min(1.12,.45+.28*(raw.MAXMP||0)/75+.27*(raw.WIS||0)/8)))*100)/100,affix:'block',affixAmount:Math.max(0,Math.min(8,Math.round(def*6/17)))}}
function armorDisplayStats(d){const v=armorStatRecipe(d.mechanic.armorProfile);for(const k in v)if(v[k]>0)v[k]*=d.mechanic.armorShiny||1;if(d.effect==='heal')v.vitality=0;return v}
function armorTitle(p){return p.name==='Cackling Straitjacket'?'Chaotic frenzy':p.kind==='plate'?'Heavy armor':p.kind==='leather'?'Leather armor':'Robe'}
function armorSummary(d){const p=d.mechanic.armorProfile,v=armorDisplayStats(d),parts=[d.effect==='heal'?`Heal ${d.amount} HP`:d.effect==='block'?`Gain ${d.amount} block`:d.effect==='dodge'?'Gain 1 dodge':`Generate 2 mana${d.affixAmount?' and '+d.affixAmount+' block':''}`];if(v.health)parts.push(`${v.health>0?'+':''}${Math.round(v.health)} max HP`);if(v.magic)parts.push(`${v.magic>0?'+':''}${Math.round(v.magic)} max mana`);if(v.attack)parts.push(`${v.attack>0?'+':''}${Number(v.attack.toFixed(2))}% adjacent weapon damage`);if(p.procs.length)parts.push(armorShortProc(p.procs[0]));return parts.slice(0,4).join('. ')+'.'}
function armorShortProc(p){return ({damage:'Conditional counterattack',heal:'Conditional healing',healField:'Conditional healing field',mana:'Conditional mana recovery',poison:'Conditional '+(p.status==='burn'?'fire':'poison')+' burst',pet:'Conditional companion',stat:'Conditional stat boost',reduction:'Taking a hit can reduce later damage',condition:p.effect==='Invulnerable'?'Brief protection on an eligible trigger':'Conditional '+p.effect,status:'Conditional enemy debuff'})[p.kind]||'Conditional effect'}
function armorStatText(v){return Object.entries(v).filter(([k,v])=>v).map(([k,value])=>{const v=Number(value.toFixed(2));return ({health:`${v>0?'+':''}${Math.round(v)} max HP`,magic:`${v>0?'+':''}${Math.round(v)} max mana`,attack:`${v}% adjacent weapon output`,dexterity:`${v}% adjacent weapon recharge`,speed:`${Math.abs(v)}% ${v>=0?'shorter':'longer'} adjacent cooldowns`,wisdom:`${v}% adjacent ability output`,vitality:v>0?`${v} healing / 5s`:`${-v}% less healing`})[k]}).join('; ')}
function armorStatProcText(p,n){const v=Math.abs(n),time=p.duration;return ({ATT:`adjacent weapons deal ${v}% ${n>=0?'more':'less'} damage for ${time}s`,DEX:`adjacent weapons recharge ${v}% ${n>=0?'faster':'slower'} for ${time}s`,SPD:n>=0?`adjacent cooldowns are ${v}% shorter for ${time}s`:`your item cooldowns are ${v}% longer for ${time}s`,DEF:n>=0?`this armor and adjacent items gain ${v}% more block for ${time}s`:`incoming damage rises ${v}% and this armor/adjacent block falls ${v}% for ${time}s`,WIS:`adjacent abilities gain ${n}% output for ${time}s`,VIT:`heal ${Math.min(12,Math.round(n))} HP over ${time}s`,MAXHP:`gain ${Math.min(12,Math.round(n))} temporary block`,MAXMP:`recover ${Math.min(4,Math.round(n))} mana`})[p.stat]}
