function armorRuleText(d){const p=d.mechanic.armorProfile,v=armorDisplayStats(d);delete v.health;delete v.magic;delete v.attack;const stats=armorStatText(v),groups=new Map();if(p.name==='Cackling Straitjacket')return (stats?stats+'. ':'')+'After 100 weapon uses across battles, trigger a 3s frenzy: gain 6 block and 3 mana; adjacent weapons gain +2.4% damage and +1.8% recharge, nearby item block gains +2.1%, and adjacent abilities gain +1.8% output. Heal 7 HP over 3s. Confusion also reduces adjacent weapon output by 10% for 3s.';for(const x of p.procs){const key=x.event+':'+x.kind+':'+(x.stat||x.effect||'');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(x)}return [stats,...[...groups.values()].map(group=>armorProcText(group,d)),p.discount?`${Math.round(p.discount*100)}% ability mana refund; strongest gear discount only, shared 20% limit. Afford the cast first.`:'',p.meterMax?'Defeated waves charge this item by 300 (boss: 1500), up to '+p.meterMax+'. Charged effects spend their listed meter cost.':'',...p.notes].filter(Boolean).join('. ')}
function armorPacked(){if(!s)return [];const cache=prepareCombatGeometry();if(cache?.armorItems)return cache.armorItems;const result=s.items.filter(i=>defs[i.type].armorIdentity);if(cache)cache.armorItems=result;return result}
