function armorArmored(){return armorPacked().some(i=>armorBuffValue(i,'armored')>0)}
function armorIncomingMultiplier(){const reduction=Math.max(0,...armorPacked().map(i=>armorBuffValue(i,'reduction'))),risk=Math.min(.15,[...armorPacked(),...abilityPacked()].reduce((n,i)=>n+(Math.max(0,-armorBuffValue(i,'defense'))+(defs[i.type].abilityIdentity?Math.max(0,-abilityStatRecipe(defs[i.type].mechanic.abilityProfile).defense):0))/100,0));return (1-Math.min(.15,reduction))*(1+risk)}
function armorEligible(i,p,amount){const c=p.conditions||{},ratio=s.hp/s.max,ids=new Set(s.items.map(j=>Number((defs[j.type].baseId||j.type).slice(5)))),all=v=>v.split(';').every(id=>ids.has(parseInt(id,16))),any=v=>v.split(';').some(id=>ids.has(parseInt(id,16)));if(s.hp<=0)return false;if(c.MustWear&&!all(c.MustWear)||c.MustNotWear&&any(c.MustNotWear)||c.MustNotWearOR&&any(c.MustNotWearOR))return false;if(c.HpMinThresholdRelative&&ratio>+c.HpMinThresholdRelative||c.HpRequiredRelative&&ratio<+c.HpRequiredRelative||c.DamageThreshold&&amount<Math.max(1,+c.DamageThreshold*.2)||c.ManaMinThresholdRelative&&s.mana>manaCapacity()*+c.ManaMinThresholdRelative)return false;if(p.meter&&(i.armorMeter||0)<p.meter)return false;const req=c.RequiredConditions;if(['MP Debuff','WIS Debuff'].includes(req)){const role=req==='MP Debuff'?'magic':'wisdom';if(!specialRingPacked().some(j=>(specialRingStats(j)[role]||0)<0)&&!armorPacked().some(j=>(armorStats(j)[role]||0)<0))return false}if(req==='Healing'&&s.time-(s.realmLastHeal??-1000)>3||req==='Invisible'&&s.time>=(s.ringCloakUntil||0)||req==='Stasis Immune'&&!armorBuffValue(i,'barrage'))return false;return true}
function armorEffect(i,p){switch(p.kind){case'damage':swordHit(p.amount,p.pierce||0);if(p.bleed)apply('bleed',p.bleed,i);if(p.chill)s.enemy.chill=Math.max(s.enemy.chill,p.chill);if(p.expose)s.enemy.vulnerable=Math.max(s.enemy.vulnerable,p.expose);break;case'heal':restore(p.amount,true,i);break;case'healField':specialRingField(i,'heal',p.amount,p.duration);break;case'mana':gainMana(p.amount,i);break;case'poison':swordHit(p.impact||0);apply(p.status,p.amount,i);break;case'pet':{let pet=p.pet;if(pet.kind==='slime'){const state=specialState(i);state.slimeCycle=(state.slimeCycle||0)+1;pet={...pet,kind:state.slimeCycle%2?'blueSlime':'greenSlime',pierce:state.slimeCycle%2?0:1}}return specialRingSpawn(i,pet)}case'reduction':armorBuff(i,'reduction',p.amount,p.duration);break;case'stat':{const role={ATT:'attack',DEX:'dexterity',SPD:'speed',DEF:'defense',WIS:'wisdom'}[p.stat];if(role)armorBuff(i,role,p.amount,p.duration);else if(p.stat==='VIT')specialRingField(i,'heal',Math.min(12,Math.round(p.amount)),p.duration);else if(p.stat==='MAXHP')gainBlock(Math.min(12,Math.round(p.amount)),i);else if(p.stat==='MAXMP')gainMana(Math.min(4,Math.round(p.amount)),i);break}case'status':s.enemy.chill=Math.max(s.enemy.chill,Math.min(3,p.duration));break;case'condition':switch(p.effect){case'Invulnerable':if(s.time<(s.armorProtectionReady||0))return false;s.armorProtectionReady=s.time+20;armorBuff(i,'protection',1,p.duration);break;case'Armored':armorBuff(i,'armored',1,p.duration);break;case'Invisible':s.dodge=Math.min(3,s.dodge+1);s.ringCloakUntil=s.time+Math.min(4,p.duration);break;case'Healing':specialRingField(i,'heal',p.amount,p.duration);break;case'Energized':specialRingField(i,'mana',Math.min(4,Math.ceil(p.duration)),p.duration);break;case'Dazed':armorBuff(i,'dazed',15,p.duration);break;case'Slowed':armorBuff(i,'speed',-15,p.duration);break;case'Hexed':armorBuff(i,'confusionPenalty',10,p.duration);break;case'Stasis Immune':armorBuff(i,'barrage',1,p.duration);break;case'Hallucinating':armorBuff(i,'confusion',1,p.duration);break}break}return true}
function armorEvent(event,amount=1,source=null){if(s.phase!=='fight'||s.hp<=0||s.armorDispatch)return;if(['weapon','ability','hit'].includes(event)&&(!source||!s.items.includes(source)||defs[source.type].group!==(event==='ability'?'ability':'weapon')))return;const items=armorPacked();if(!items.length)return;s.armorDispatch=true;try{const candidates=new Map(),costs=new Map(),strength=p=>Math.abs(p.amount||0)+(p.pet?(p.pet.power||0)+(p.pet.heal||0):0);for(const i of items)for(const p of defs[i.type].mechanic.armorProfile.procs){if(p.event!==event||!armorEligible(i,p,amount))continue;const old=candidates.get(p.channel);if(!old||strength(p)>strength(old.p)||strength(p)===strength(old.p)&&p.duration>old.p.duration)candidates.set(p.channel,{i,p})}s.armorLocks??={};s.armorCharges??={};s.armorProcCredits??={};for(const [key,{i,p}]of candidates){if(s.time<(s.armorLocks[key]||0))continue;const credit=defs[i.type].mechanic.armorProfile.family+':'+key,charge=Math.min(100,(s.armorProcCredits[credit]||0)+p.chance*100);s.armorCharges[key]=charge;s.armorProcCredits[credit]=charge;if(charge+1e-8<100)continue;if(armorEffect(i,p)!==false){s.armorCharges[key]=s.armorProcCredits[credit]=Math.max(0,charge-100);s.armorLocks[key]=s.time+p.cooldown;costs.set(i,Math.max(costs.get(i)||0,p.meterCost||0));itemFxPulse(i,'utility','◆')}}for(const [i,cost]of costs)if(cost)i.armorMeter=Math.max(0,(i.armorMeter||0)-cost);if(event==='ability'&&source){const ring=Math.max(0,...specialRingPacked().map(i=>defs[i.type].mechanic.ringProfile.discount)),best=Math.min(.2,Math.max(ring,...items.map(i=>defs[i.type].mechanic.armorProfile.discount))),discount=Math.max(0,best-ring);if(discount){s.armorManaCredit=(s.armorManaCredit||0)+itemManaCost(defs[source.type],source)*discount;const n=Math.floor(s.armorManaCredit+1e-8);s.armorManaCredit-=n;if(n)gainMana(n,items[0])}}}finally{s.armorDispatch=false}}
function resetArmorMechanics(){s.armorProcCredits??={};s.armorLocks={};s.armorCharges={};s.armorManaCredit=0;s.armorProtectionReady=0;s.armorDispatch=false;s.armorVictories=[]}
function tickArmorMechanics(dt){const unique=new Map();for(const i of armorPacked()){if(defs[i.type].effect==='heal')continue;const family=defs[i.type].mechanic.armorProfile.family,old=unique.get(family);if(!old||armorStats(i).vitality>armorStats(old).vitality)unique.set(family,i)}for(const i of [...unique.values()].filter(i=>armorStats(i).vitality>0).sort((a,b)=>armorStats(b).vitality-armorStats(a).vitality).slice(0,2)){const state=specialState(i);if(s.time+1e-8>=(state.nextArmorHeal??5)){state.nextArmorHeal=s.time+5;state.armorHealCarry=(state.armorHealCarry||0)+armorStats(i).vitality;const n=Math.floor(state.armorHealCarry+1e-8);state.armorHealCarry-=n;if(n)restore(n,true,i)}}}
function armorEnemyDefeated(){const key=s.room+':'+s.enemy.wave;s.armorVictories??=[];if(s.armorVictories.includes(key))return;s.armorVictories.push(key);for(const i of armorPacked()){const p=defs[i.type].mechanic.armorProfile;if(p.meterMax)i.armorMeter=Math.min(p.meterMax,(i.armorMeter||0)+(ROOMS[s.room].type==='boss'?1500:300))}}
function armorStateText(i){const v={...armorStats(i)},p=defs[i.type].mechanic.armorProfile;if(defs[i.type].effect==='heal')v.vitality=0;return armorStatText(v)+(p.meterMax?' · Charge: '+(i.armorMeter||0)+'/'+p.meterMax:'')+(armorBuffValue(i,'protection')?' · Protected':'')+(p.procs.some(p=>p.chance<1)?' · Chance charge: '+Math.round(Math.max(0,...p.procs.filter(x=>x.chance<1).map(x=>s.armorProcCredits?.[p.family+':'+x.channel]||0)))+'%':'')+(armorBuffValue(i,'confusionPenalty')?' · Confused: adjacent weapon output -10%':'')}
function armorWeaponHit(i,activation){if(!i||defs[i.type].group!=='weapon'||!abilityPacked().length&&!armorPacked().some(j=>defs[j.type].mechanic.armorProfile.procs.some(p=>p.event==='hit')))return;const state=specialState(i);state.armorHits??=[];if(state.armorHits.includes(activation))return;state.armorHits.push(activation);if(state.armorHits.length>24)state.armorHits.shift();armorEvent('hit',1,i);abilityEvent('hit',1,i)}
function armorProjectileImpact(p,dagger=false){const before=s.enemy.hp+(s.enemy.ward||0),dealt=dagger?daggerHit(p.damage,p.pierce||0):swordHit(p.damage,p.pierce||0);if(s.enemy.hp+(s.enemy.ward||0)<before){const i=s.items.find(i=>i.id===p.source);if(i)armorWeaponHit(i,p.armorActivation??i.activations)}return dealt}
